using DriveOS.Modules.Workforce.Domain.PerformanceReviews;
using DriveOS.SharedKernel.Identifiers;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.Workforce.Infrastructure.Persistence.Configurations;

internal sealed class PerformanceReviewConfiguration : IEntityTypeConfiguration<PerformanceReview> { public void Configure(EntityTypeBuilder<PerformanceReview> b) { b.ToTable("performance_reviews"); b.HasKey(x => x.Id); b.Property(x => x.Id).HasConversion(x => x.Value, x => new PerformanceReviewId(x)).ValueGeneratedNever(); b.Property(x => x.OrganizationId).HasConversion(x => x.Value, x => new OrganizationId(x)); b.Property(x => x.EmployeeId).HasConversion(x => x.Value, x => new EmployeeId(x)); b.Property(x => x.EvaluatorUserId).HasConversion(x => x.Value, x => new UserId(x)); b.Property(x => x.Status).HasConversion<int>(); b.Property(x => x.Title).HasMaxLength(160); b.Property(x => x.OverallAssessment).HasMaxLength(4000); b.Property(x => x.Objectives).HasMaxLength(4000); b.Property(x => x.EmployeeComment).HasMaxLength(4000); b.Property(x => x.CancellationReason).HasMaxLength(512); foreach (var n in new[] { nameof(PerformanceReview.SubmittedByUserId), nameof(PerformanceReview.AcknowledgedByUserId), nameof(PerformanceReview.CompletedByUserId), nameof(PerformanceReview.CreatedByUserId), nameof(PerformanceReview.LastModifiedByUserId) }) b.Property<UserId?>(n).HasConversion(x => x.HasValue ? x.Value.Value : (Guid?)null, x => x.HasValue ? new UserId(x.Value) : null); b.HasMany(x => x.Criteria).WithOne().HasForeignKey("performance_review_id").IsRequired().OnDelete(DeleteBehavior.Cascade); b.Navigation(x => x.Criteria).UsePropertyAccessMode(PropertyAccessMode.Field); b.HasIndex(x => new { x.OrganizationId, x.EmployeeId, x.Status }); b.HasIndex(x => new { x.OrganizationId, x.PeriodFrom, x.PeriodTo }); } }
internal sealed class PerformanceReviewCriterionConfiguration : IEntityTypeConfiguration<PerformanceReviewCriterion> { public void Configure(EntityTypeBuilder<PerformanceReviewCriterion> b) { b.ToTable("performance_review_criteria"); b.HasKey(x => x.Id); b.Property(x => x.Id).HasConversion(x => x.Value, x => new PerformanceReviewCriterionId(x)).ValueGeneratedNever(); b.Property(x => x.Code).HasMaxLength(64); b.Property(x => x.Label).HasMaxLength(256); b.Property(x => x.Comment).HasMaxLength(2000); b.HasIndex("performance_review_id", nameof(PerformanceReviewCriterion.Code)).IsUnique(); } }
